OUT=Path(__file__).resolve().parents[2]/'outputs/exchange-messaging';DB='qm_oms_saas_order';CH='qm_oms_saas_channel';SRC='refund_acceptance_source'
def main():
 OUT.mkdir(parents=True,exist_ok=True);token=login();case={'stamp':datetime.now().strftime('%Y%m%d%H%M%S'),'checks':[]};original={}
 def save():(OUT/'case.json').write_text(json.dumps(case,ensure_ascii=False,indent=2),encoding='utf-8')
