 def seed(index,version=1,status='1'):
  rid='98'+case['stamp']+str(index).zfill(3);modified=case['source_time'] if version==1 else datetime.now().strftime('%Y-%m-%d %H:%M:%S');payload={'dispute_id':rid,'biz_order_id':case['tid']+'1','num':1,'status':status,'good_status':'未发货','modified':modified,'time_out':(datetime.now()+timedelta(days=2)).strftime('%Y-%m-%d %H:%M:%S'),'bought_sku':'[队列验收] 原规格 A','exchange_sku':'[队列验收] 目标规格 B','speed_exchange':0,'refund_phase':'onsale'}
